const OMEGA_SECURITY_WORK_BLOCK_PREFIX: &str = "block:omega:security-work:";

fn omega_thread_route(thread_id: ThreadId) -> Option<OmegaRoute> {
    OmegaRoute::thread(thread_id.to_key_string())
        .map_err(|error| log::error!("could not construct a thread route: {error}"))
        .ok()
}

fn omega_forensics_route(work_ref: &str) -> Option<OmegaRoute> {
    DomainBlockRoute::new(
        format!("{OMEGA_SECURITY_WORK_BLOCK_PREFIX}{work_ref}"),
        "forensics",
    )
    .and_then(|block| OmegaRoute::work(work_ref, Some(block)))
    .map_err(|error| log::error!("could not construct the Forensics work route: {error}"))
    .ok()
}

fn is_omega_forensics_route(route: &OmegaRoute) -> bool {
    matches!(
        route,
        OmegaRoute::Work(work)
            if work.block.as_ref().is_some_and(|block| {
                    block.block_ref.as_str().starts_with(OMEGA_SECURITY_WORK_BLOCK_PREFIX)
                        && block.domain.as_str() == "forensics"
                })
    )
}

fn work_issue_identifier(work_ref: &str) -> Option<omega_effectd::all_work_contract::ShortText> {
    let mut digest = Sha256::new();
    digest.update(work_ref.as_bytes());
    let digest = format!("{:x}", digest.finalize());
    let Some(prefix) = digest.get(..8) else {
        log::warn!("could not derive the Issue identifier digest");
        return None;
    };
    omega_effectd::all_work_contract::ShortText::try_from(format!("OMEGA-{prefix}"))
        .map_err(|error| log::warn!("could not construct the Issue identifier: {error}"))
        .ok()
}

fn work_event_ref(
    work_ref: &str,
    revision: u64,
) -> Option<omega_effectd::all_work_contract::EventRef> {
    let mut digest = Sha256::new();
    digest.update(work_ref.as_bytes());
    let digest = format!("{:x}", digest.finalize());
    let Some(prefix) = digest.get(..16) else {
        log::warn!("could not derive the Work Event digest");
        return None;
    };
    omega_effectd::all_work_contract::EventRef::try_from(format!(
        "event:omega:work-detail:{prefix}:{revision}"
    ))
    .map_err(|error| log::warn!("could not construct the Work Event reference: {error}"))
    .ok()
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ToolbarMode {
    Terminal,
    EmptyThread,
    ActiveThread,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct ToolbarSurfaceState {
    mode: ToolbarMode,
    show_thread_details: bool,
}

fn toolbar_surface_state(
    showing_admission_surface: bool,
    base_is_terminal: bool,
    active_thread_has_messages: bool,
) -> ToolbarSurfaceState {
    if showing_admission_surface {
        return ToolbarSurfaceState {
            mode: ToolbarMode::EmptyThread,
            show_thread_details: false,
        };
    }

    let mode = if base_is_terminal {
        ToolbarMode::Terminal
    } else if active_thread_has_messages {
        ToolbarMode::ActiveThread
    } else {
        ToolbarMode::EmptyThread
    };
    ToolbarSurfaceState {
        mode,
        show_thread_details: true,
    }
}

/// One executor row in the composer's new-conversation dropdown.
///
/// `OMEGA-DELTA-0184`, omega#165. The typed target and readiness model from
/// the #151 front door survives here — the interstitial screen died, its law
/// did not. Every row is present whether or not it can run, so a missing
/// executor reads as a disabled reason instead of an absence.
#[derive(Clone)]
pub(crate) struct ComposerExecutorRow {
    pub(crate) target: ConversationTarget,
    pub(crate) label: SharedString,
    pub(crate) readiness: ModeReadiness,
    pub(crate) is_current: bool,
}

impl ComposerExecutorRow {
    /// Whether picking this row can do something on this machine right now.
    ///
    /// Ready rows and rows whose setup the selection itself performs are
    /// selectable. Rows that cannot run here — not installed, not supported
    /// in this build, or transiently unavailable — render disabled with the
    /// reason, never hidden and never fake-enabled.
    pub(crate) fn is_selectable(&self) -> bool {
        match &self.readiness {
            ModeReadiness::Ready { .. } => true,
            ModeReadiness::SetupRequired { action, .. } => matches!(
                action,
                ModeSetupAction::PrepareOmegaAgent
                    | ModeSetupAction::PrepareDirectAgent
                    | ModeSetupAction::RevealPreparedConversation
            ),
            ModeReadiness::TemporarilyUnavailable { .. }
            | ModeReadiness::NotSupportedInBuild { .. } => false,
        }
    }
}

