    #[test]
    fn entropy_task_prompt_makes_snapshot_handling_an_agent_responsibility() {
        let candidate = crate::thread_identity::ThreadIdentityCandidate {
            binding: omega_workbench_state::RepositoryBinding::new("repo", "worktree")
                .expect("valid binding"),
            git_repository_id: Some(1),
            project_name: "Omega".into(),
            repository_name: "omega".into(),
            worktree_name: "omega".into(),
            worktree_abs_path: PathBuf::from("/work/omega"),
            worktree_path: "/work/omega".into(),
            remote_url: Some("https://github.com/OpenAgentsInc/omega.git".into()),
            head_commit: Some("0123456789abcdef0123456789abcdef01234567".into()),
            branch: crate::thread_identity::BranchIdentity::Branch("main".into()),
            git: crate::thread_identity::GitIdentitySummary {
                dirty_files: 3,
                ..Default::default()
            },
            source_revision: 1,
        };
        let snapshot = omega_forensics::EntropyPromptSnapshot::new(
            "prompt.omega.entropy.test".to_string(),
            None,
            None,
            "Trace every entropy source and secret consumer.".to_string(),
            "2026-08-02T20:30:00.000Z".to_string(),
        )
        .expect("valid prompt snapshot");

        let prompt = entropy_agent_task_prompt(&candidate, &snapshot);

        assert!(prompt.contains("Run a read-only entropy forensics scan"));
        assert!(prompt.contains("dirty (3 changed files)"));
        assert!(prompt.contains("0123456789abcdef0123456789abcdef01234567"));
        assert!(prompt.contains("create a temporary clean detached worktree or local clone"));
        assert!(prompt.contains("do not ask the user to pin or prepare a worktree"));
        assert!(prompt.contains("Trace every entropy source and secret consumer."));
        assert!(prompt.contains("Present the final result as readable Markdown"));
        assert!(prompt.contains("Entropy scan complete with limitations"));
    }

    #[test]
    fn dirty_entropy_repository_uses_a_clean_pinned_snapshot() {
        let repository = tempfile::tempdir().expect("temporary Git repository");
        let source_path = repository.path().join("entropy.rs");
        std::fs::write(&source_path, "const SOURCE: &str = \"committed\";\n")
            .expect("write committed source");
        let git = |arguments: &[&str]| {
            let output = smol::block_on(
                smol::process::Command::new("git")
                    .arg("-C")
                    .arg(repository.path())
                    .args(arguments)
                    .output(),
            )
            .expect("run Git command");
            assert!(
                output.status.success(),
                "Git command failed: {}",
                String::from_utf8_lossy(&output.stderr)
            );
            output
        };
        git(&["init", "--quiet"]);
        git(&["add", "entropy.rs"]);
        git(&[
            "-c",
            "user.name=Omega Test",
            "-c",
            "user.email=omega@example.invalid",
            "commit",
            "--quiet",
            "-m",
            "fixture",
        ]);
        let revision = String::from_utf8(git(&["rev-parse", "HEAD"]).stdout)
            .expect("UTF-8 revision")
            .trim()
            .to_string();
        std::fs::write(&source_path, "const SOURCE: &str = \"dirty\";\n")
            .expect("write dirty source");

        let checkout = smol::block_on(materialize_entropy_repository_checkout(
            repository.path(),
            &revision,
        ))
        .expect("materialize pinned source");
        let checkout_root = checkout.root().to_path_buf();
        assert_eq!(
            std::fs::read_to_string(checkout_root.join("entropy.rs"))
                .expect("read snapshot source"),
            "const SOURCE: &str = \"committed\";\n"
        );
        assert_eq!(
            String::from_utf8(
                smol::block_on(
                    smol::process::Command::new("git")
                        .arg("-C")
                        .arg(&checkout_root)
                        .args(["rev-parse", "HEAD"])
                        .output(),
                )
                .expect("read snapshot revision")
                .stdout,
            )
            .expect("UTF-8 snapshot revision")
            .trim(),
            revision
        );
        drop(checkout);
        assert!(!checkout_root.exists());
    }

    #[test]
    fn omega_navigation_history_walks_and_branches_like_a_browser() {
        let first = ThreadId::new();
        let third = ThreadId::new();
        let branch = ThreadId::new();
        let mut history = OmegaNavigationHistory::default();
        let thread_route = |thread_id| omega_thread_route(thread_id).expect("valid thread route");

        history.push(thread_route(first));
        history.push(OmegaRoute::Settings);
        history.push(thread_route(third));
        assert!(history.can_back());
        assert!(!history.can_forward());
        assert_eq!(history.back(), Some(OmegaRoute::Settings));
        assert_eq!(history.back(), Some(thread_route(first)));
        assert_eq!(history.back(), None);
        assert!(history.can_forward());
        assert_eq!(history.forward(), Some(OmegaRoute::Settings));

        history.push(thread_route(branch));
        assert_eq!(history.back(), Some(OmegaRoute::Settings));
        assert_eq!(history.forward(), Some(thread_route(branch)));
        assert_eq!(history.forward(), None);
    }

    #[test]
    fn omega_navigation_history_retains_unavailable_targets() {
        let first = ThreadId::new();
        let unavailable = ThreadId::new();
        let current = ThreadId::new();
        let mut history = OmegaNavigationHistory::default();
        let thread_route = |thread_id| omega_thread_route(thread_id).expect("valid thread route");

        history.push(thread_route(first));
        history.push(thread_route(unavailable));
        history.push(thread_route(current));

        assert!(history.can_back());
        assert_eq!(history.back(), Some(thread_route(unavailable)));
        assert_eq!(history.back(), Some(thread_route(first)));
    }

    #[test]
    fn omega_navigation_migrates_legacy_panel_state_and_rejects_invalid_history() {
        let legacy_panel: SerializedAgentPanel = serde_json::from_value(json!({
            "selected_agent": null
        }))
        .expect("legacy panel JSON without entity navigation remains readable");
        assert!(legacy_panel.omega_navigation.is_none());

        let invalid = PersistedEntityNavigation {
            schema: "openagents.omega.entity-navigation.v99".to_string(),
            entries: vec![OmegaRoute::Settings],
            index: 0,
        };
        let restored = restore_omega_navigation(Some(invalid), Some("thread:legacy"));
        assert_eq!(
            restored.current(),
            Some(&OmegaRoute::thread("thread:legacy").expect("valid legacy thread route"))
        );

        let restored_from_empty = restore_omega_navigation(
            Some(OmegaNavigationHistory::default().persisted()),
            Some("thread:legacy"),
        );
        assert_eq!(restored_from_empty.current(), restored.current());
    }

    #[gpui::test]
    async fn omega_repository_list_keeps_each_opened_repository(cx: &mut TestAppContext) {
        init_test(cx);
        let fs = FakeFs::new(cx.executor());
        fs.insert_tree("/project-a", json!({ "file.txt": "" }))
            .await;
        fs.insert_tree("/project-b", json!({ "file.txt": "" }))
            .await;
        let project_a = Project::test(fs.clone(), [Path::new("/project-a")], cx).await;
        let project_b = Project::test(fs, [Path::new("/project-b")], cx).await;
        let multi_workspace =
            cx.add_window(|window, cx| MultiWorkspace::test_new(project_a, window, cx));
        multi_workspace
            .update(cx, |multi_workspace, window, cx| {
                multi_workspace.test_add_workspace(project_b, window, cx);
            })
            .expect("second project should open in the current window");

        let mut names = multi_workspace
            .read_with(cx, |multi_workspace, cx| {
                omega_repository_workspaces(multi_workspace, cx)
                    .into_iter()
                    .map(|(_, _, name)| name.to_string())
                    .collect::<Vec<_>>()
            })
            .expect("project rows should be readable");
        names.sort();
        assert_eq!(names, ["project-a", "project-b"]);
    }

