    /// The settings-footer version is short and channel-honest: stable shows
    /// only the version, a stamped build shows `v0.2.0 b28`, and an unstamped
    /// (dev/source) build shows `v0.2.0 dev`. The full commit sha never
    /// appears in the footer; it stays in About, `omega: copy system specs`,
    /// and the release record.
    #[gpui::test]
    fn footer_version_label_formats(cx: &mut TestAppContext) {
        cx.update(|cx| {
            release_channel::init(semver::Version::new(0, 2, 0), cx);
            // The test binary compiles on the dev channel, so an unstamped
            // build renders the dev suffix...
            assert_eq!(footer_version_label(cx), "v0.2.0 dev");
            // ...and a stamped build renders the per-version build number.
            release_channel::AppBuildNumber::set_global(
                release_channel::AppBuildNumber::new(28),
                cx,
            );
            assert_eq!(footer_version_label(cx), "v0.2.0 b28");
            // Build metadata on the version (channel + sha, as
            // `AppVersion::load` produces for a bundle) must never leak into
            // the footer.
            let mut stamped = semver::Version::new(0, 2, 0);
            stamped.build =
                semver::BuildMetadata::new("preview.c9c27d9171deadbeef").expect("valid metadata");
            release_channel::init(stamped, cx);
            assert_eq!(footer_version_label(cx), "v0.2.0 b28");
        });
    }

    #[test]
    fn front_door_toolbar_ignores_every_hidden_base_surface_state() {
        for (base_is_terminal, active_thread_has_messages) in
            [(false, false), (false, true), (true, false), (true, true)]
        {
            assert_eq!(
                toolbar_surface_state(true, base_is_terminal, active_thread_has_messages),
                ToolbarSurfaceState {
                    mode: ToolbarMode::EmptyThread,
                    show_thread_details: false,
                }
            );
        }

        assert_eq!(
            toolbar_surface_state(false, false, true),
            ToolbarSurfaceState {
                mode: ToolbarMode::ActiveThread,
                show_thread_details: true,
            }
        );
        assert_eq!(
            toolbar_surface_state(false, true, true),
            ToolbarSurfaceState {
                mode: ToolbarMode::Terminal,
                show_thread_details: true,
            }
        );
    }

