    #[gpui::test]
    async fn test_workspaces_maintain_independent_agent_selection(cx: &mut TestAppContext) {
        init_test(cx);
        cx.update(|cx| {
            agent::ThreadStore::init_global(cx);
            language_model::LanguageModelRegistry::test(cx);
        });

        let fs = FakeFs::new(cx.executor());
        let project_a = Project::test(fs.clone(), [], cx).await;
        let project_b = Project::test(fs, [], cx).await;

        let multi_workspace =
            cx.add_window(|window, cx| MultiWorkspace::test_new(project_a.clone(), window, cx));

        let workspace_a = multi_workspace
            .read_with(cx, |multi_workspace, _cx| {
                multi_workspace.workspace().clone()
            })
            .unwrap();

        let workspace_b = multi_workspace
            .update(cx, |multi_workspace, window, cx| {
                multi_workspace.test_add_workspace(project_b.clone(), window, cx)
            })
            .unwrap();

        workspace_a.update(cx, |workspace, _cx| {
            workspace.set_random_database_id();
        });
        workspace_b.update(cx, |workspace, _cx| {
            workspace.set_random_database_id();
        });

        let cx = &mut VisualTestContext::from_window(multi_workspace.into(), cx);

        let agent_a = Agent::Custom {
            id: "agent-alpha".into(),
        };
        let agent_b = Agent::Custom {
            id: "agent-beta".into(),
        };

        // Set up workspace A with agent_a
        let panel_a = workspace_a.update_in(cx, |workspace, window, cx| {
            cx.new(|cx| AgentPanel::new(workspace, window, cx))
        });
        panel_a.update(cx, |panel, _cx| {
            panel.selected_agent = agent_a.clone();
        });

        // Set up workspace B with agent_b
        let panel_b = workspace_b.update_in(cx, |workspace, window, cx| {
            cx.new(|cx| AgentPanel::new(workspace, window, cx))
        });
        panel_b.update(cx, |panel, _cx| {
            panel.selected_agent = agent_b.clone();
        });

        // Serialize both panels
        panel_a.update(cx, |panel, cx| panel.serialize(cx));
        panel_b.update(cx, |panel, cx| panel.serialize(cx));
        cx.run_until_parked();

        // Load fresh panels from serialized state and verify independence
        let async_cx = cx.update(|window, cx| window.to_async(cx));
        let loaded_a = AgentPanel::load(workspace_a.downgrade(), async_cx)
            .await
            .expect("panel A load should succeed");
        cx.run_until_parked();

        let async_cx = cx.update(|window, cx| window.to_async(cx));
        let loaded_b = AgentPanel::load(workspace_b.downgrade(), async_cx)
            .await
            .expect("panel B load should succeed");
        cx.run_until_parked();

        loaded_a.read_with(cx, |panel, _cx| {
            assert_eq!(
                panel.selected_agent, agent_a,
                "workspace A should restore agent-alpha, not agent-beta"
            );
        });

        loaded_b.read_with(cx, |panel, _cx| {
            assert_eq!(
                panel.selected_agent, agent_b,
                "workspace B should restore agent-beta, not agent-alpha"
            );
        });
    }

    #[gpui::test]
    async fn test_new_thread_defaults_to_omega_and_syncs_the_selection(cx: &mut TestAppContext) {
        init_test(cx);
        let fs = FakeFs::new(cx.executor());
        cx.update(|cx| {
            agent::ThreadStore::init_global(cx);
            language_model::LanguageModelRegistry::test(cx);
            <dyn fs::Fs>::set_global(fs.clone(), cx);
        });

        fs.insert_tree("/project", json!({ "file.txt": "" })).await;
        let project = Project::test(fs.clone(), [Path::new("/project")], cx).await;

        let multi_workspace =
            cx.add_window(|window, cx| MultiWorkspace::test_new(project.clone(), window, cx));

        let workspace = multi_workspace
            .read_with(cx, |multi_workspace, _cx| {
                multi_workspace.workspace().clone()
            })
            .unwrap();

        workspace.update(cx, |workspace, _cx| {
            workspace.set_random_database_id();
        });

        let cx = &mut VisualTestContext::from_window(multi_workspace.into(), cx);

        let custom_agent = Agent::Custom {
            id: "my-custom-agent".into(),
        };

        let panel = workspace.update_in(cx, |workspace, window, cx| {
            let panel = cx.new(|cx| AgentPanel::new(workspace, window, cx));
            workspace.add_panel(panel.clone(), window, cx);
            panel
        });

        // Set selected_agent to a custom agent
        panel.update(cx, |panel, _cx| {
            panel.selected_agent = custom_agent.clone();
        });

        cx.focus(&workspace);
        cx.dispatch_action(NewThread);
        cx.run_until_parked();

        panel.update_in(cx, |panel, window, cx| {
            // omega#165: `+` lands on the default executor. There is no
            // hidden second selection store left behind — the dropdown is the
            // one authority, and it reads the conversation it sits under.
            assert_eq!(
                panel.selected_agent,
                Agent::NativeAgent,
                "NewThread defaults to Omega and syncs the stored selection to it"
            );
            assert!(
                panel.front_door_composer_visible_for_tests(),
                "NewThread lands in the focused composer draft"
            );
            assert!(matches!(
                panel
                    .draft_thread
                    .as_ref()
                    .map(|draft| draft.read(cx).agent_key()),
                Some(Agent::NativeAgent)
            ));
            let composer_focus = panel
                .active_conversation_view()
                .expect("Command-N must reveal a conversation")
                .read(cx)
                .activation_focus_handle(cx);
            assert!(
                composer_focus.is_focused(window),
                "Command-N must leave keyboard focus in the new thread composer"
            );
        });
    }

    #[gpui::test]
    async fn test_new_thread_leaves_forensics_for_the_composer(cx: &mut TestAppContext) {
        let (panel, mut cx) = setup_visible_panel(cx).await;

        panel.update_in(&mut cx, |panel, window, cx| {
            panel.new_thread(&NewThread, window, cx);
        });
        cx.run_until_parked();

        let draft_id = panel.read_with(&cx, |panel, _cx| {
            panel
                .draft_thread
                .as_ref()
                .expect("New Thread prepares a draft")
                .entity_id()
        });
        panel.update(&mut cx, |panel, _cx| {
            panel
                .workbench_shell
                .open_surface_for_tests(omega_workbench_state::WorkSurface::Forensics)
                .expect("the regression fixture opens Forensics");
        });
        panel.read_with(&cx, |panel, _cx| {
            let visible = panel
                .workbench_shell
                .projection()
                .visible_projection()
                .expect("the draft has a workbench projection");
            assert!(visible.dock_open);
            assert_eq!(
                panel.workbench_shell.focus_target(),
                workbench_shell::WorkbenchFocusTarget::Surface(
                    omega_workbench_state::WorkSurface::Forensics
                )
            );
        });

        panel.update_in(&mut cx, |panel, window, cx| {
            panel.new_thread(&NewThread, window, cx);
        });
        cx.run_until_parked();

        panel.read_with(&cx, |panel, _cx| {
            assert_eq!(
                panel
                    .draft_thread
                    .as_ref()
                    .expect("the blank draft remains reusable")
                    .entity_id(),
                draft_id
            );
            assert!(
                !panel
                    .workbench_shell
                    .projection()
                    .visible_projection()
                    .expect("the draft remains active")
                    .dock_open,
                "New Thread must close Forensics on a reused blank draft"
            );
            assert_eq!(
                panel.workbench_shell.focus_target(),
                workbench_shell::WorkbenchFocusTarget::Transcript
            );
            assert!(panel.front_door_composer_visible_for_tests());
        });
    }

