    #[gpui::test]
    async fn omega_entity_routes_render_and_navigate_without_thread_identity_leaks(
        cx: &mut TestAppContext,
    ) {
        let (panel, mut cx) = setup_visible_panel(cx).await;
        panel.update_in(&mut cx, |panel, window, cx| {
            panel.force_omega_primary_interface_for_tests = true;
            panel.new_thread(&NewThread, window, cx);
        });
        cx.run_until_parked();

        let omega_selectors = cx
            .debug_render_snapshot()
            .selectors()
            .map(|(selector, _)| selector.to_string())
            .filter(|selector| selector.contains("omega"))
            .collect::<Vec<_>>();
        assert!(
            cx.debug_bounds("omega.omega.sidebar.repositories")
                .is_some(),
            "rendered Omega selectors: {omega_selectors:?}"
        );
        let threads_bounds = cx
            .debug_bounds("omega.omega.sidebar.threads")
            .expect("Threads section renders");
        let experimental_bounds = cx
            .debug_bounds("omega.omega.sidebar.experimental")
            .expect("Experimental section renders");
        let forensics_bounds = cx
            .debug_bounds("omega.omega.sidebar.forensics")
            .expect("Forensics renders in Experimental");
        assert!(
            experimental_bounds.origin.y > threads_bounds.origin.y,
            "Experimental must render beneath Threads"
        );
        assert!(
            forensics_bounds.origin.y >= experimental_bounds.origin.y,
            "Forensics must render inside the Experimental section"
        );
        assert!(cx.debug_bounds("omega.omega.thread-tab.active").is_some());
        assert!(
            cx.debug_bounds("omega.omega.sidebar.work").is_none(),
            "Work section stays hidden until two native authorities have real rows"
        );
        assert!(
            cx.debug_bounds("omega.omega.sidebar.inbox").is_none(),
            "Work navigation stays hidden until two native authorities have real rows"
        );

        panel.update(&mut cx, |panel, cx| {
            let observed_at = "2026-08-02T12:00:00.000Z".to_string();
            let thread_ref = panel
                .active_thread_id(cx)
                .expect("active Thread fixture")
                .to_key_string();
            let thread = adapt_thread(NativeThreadRecord {
                thread_ref,
                title: "Question from a native thread".into(),
                updated_at: observed_at.clone(),
                observed_at: observed_at.clone(),
                revision: 1,
                archived: false,
                lifecycle: NativeThreadLifecycle::WaitingForPerson,
            })
            .expect("valid native Thread fixture");
            let forensics = adapt_forensics(NativeForensicsRecord {
                case_ref: "repository:1".into(),
                repository_name: "fixture".into(),
                updated_at: observed_at.clone(),
                observed_at: observed_at.clone(),
                revision: 1,
                phase: NativeForensicsPhase::Running,
                run_ref: Some("forensics:run:fixture".into()),
                child_run_refs: Vec::new(),
            })
            .expect("valid native Forensics fixture");
            panel
                .work_index
                .apply_native_items(
                    THREAD_ADAPTER_ID,
                    THREAD_ADAPTER_ID,
                    vec![thread],
                    observed_at.clone(),
                    1,
                )
                .expect("Thread projection qualifies");
            panel
                .work_index
                .apply_native_items(
                    FORENSICS_ADAPTER_ID,
                    FORENSICS_ADAPTER_ID,
                    forensics,
                    observed_at,
                    1,
                )
                .expect("Forensics projection qualifies");
            panel.publish_work_index(false, cx);
        });
        cx.run_until_parked();
        assert!(cx.debug_bounds("omega.omega.sidebar.work").is_some());
        assert!(cx.debug_bounds("omega.omega.sidebar.inbox").is_some());
        assert!(cx.debug_bounds("omega.omega.sidebar.my-work").is_some());

        panel.update_in(&mut cx, |panel, window, cx| {
            assert!(panel.open_work_index(WorkIndexView::Inbox, true, window, cx));
        });
        cx.run_until_parked();
        assert!(cx.debug_bounds("omega.omega.work-index.inbox").is_some());
        assert!(
            cx.debug_bounds("omega.omega.work-index-tab.active")
                .is_some()
        );
        assert!(cx.debug_bounds("omega.omega.thread-tab.active").is_none());

        cx.simulate_keystrokes("down");
        cx.run_until_parked();
        panel.read_with(&cx, |panel, _cx| {
            assert!(
                panel.work_index.selected_work_ref().is_some(),
                "keyboard navigation selects a source-backed Work row"
            );
        });
        cx.simulate_keystrokes("enter");
        cx.run_until_parked();
        assert!(cx.debug_bounds("omega.omega.work-index.inbox").is_none());
        assert!(cx.debug_bounds("omega.omega.thread-tab.active").is_some());

        panel.update_in(&mut cx, |panel, window, cx| {
            assert!(panel.open_work_index(WorkIndexView::MyWork, true, window, cx));
        });
        cx.run_until_parked();
        assert!(cx.debug_bounds("omega.omega.work-index.my-work").is_some());
        panel.update_in(&mut cx, |panel, window, cx| {
            panel.close_active_omega_route_tab(window, cx);
        });
        cx.run_until_parked();
        assert!(
            cx.debug_bounds("omega.omega.work-index-tab.active")
                .is_none()
        );
        assert!(cx.debug_bounds("omega.omega.thread-tab.active").is_some());

        let forensics_route = omega_forensics_route("work:omega:forensics:repository:1")
            .expect("valid Forensics Work route");
        panel.update(&mut cx, |panel, cx| {
            panel
                .workbench_shell
                .open_surface_for_tests(omega_workbench_state::WorkSurface::Forensics)
                .expect("open Forensics fixture");
            panel.omega_navigation_history.push(forensics_route.clone());
            cx.notify();
        });
        cx.run_until_parked();

        assert!(cx.debug_bounds("omega.omega.work-tab.active").is_some());
        assert!(cx.debug_bounds("omega.omega.thread-tab.active").is_none());
        assert!(
            cx.debug_bounds("omega.omega.sidebar-thread.active")
                .is_none()
        );
        panel.read_with(&cx, |panel, _cx| {
            assert_eq!(
                panel.omega_navigation_history.current(),
                Some(&forensics_route)
            );
        });

        panel.update_in(&mut cx, |panel, window, cx| {
            panel.close_active_omega_route_tab(window, cx);
        });
        cx.run_until_parked();
        assert!(cx.debug_bounds("omega.omega.work-tab.active").is_none());
        assert!(cx.debug_bounds("omega.omega.thread-tab.active").is_some());

        let unavailable_route =
            OmegaRoute::document("document:deleted").expect("valid unavailable document route");
        panel.update_in(&mut cx, |panel, window, cx| {
            panel
                .omega_navigation_history
                .push(unavailable_route.clone());
            panel.show_omega_unavailable_route(
                EntityRouteState {
                    route: unavailable_route.clone(),
                    availability: RouteAvailability::Unavailable(RouteUnavailableReason::Deleted),
                },
                window,
                cx,
            );
        });
        cx.run_until_parked();
        assert!(cx.debug_bounds("omega.omega.route.unavailable").is_some());
        assert!(
            cx.debug_bounds("omega.omega.route-tab.unavailable")
                .is_some()
        );
        assert!(cx.debug_bounds("omega.omega.thread-tab.active").is_none());

        panel.update_in(&mut cx, |panel, window, cx| {
            panel.navigate_omega_back(window, cx);
        });
        cx.run_until_parked();
        assert!(cx.debug_bounds("omega.omega.route.unavailable").is_none());
        assert!(cx.debug_bounds("omega.omega.thread-tab.active").is_some());

        panel.update_in(&mut cx, |panel, window, cx| {
            panel.navigate_omega_forward(window, cx);
        });
        cx.run_until_parked();
        assert!(cx.debug_bounds("omega.omega.route.unavailable").is_some());

        cx.dispatch_action(menu::Cancel);
        cx.run_until_parked();
        assert!(cx.debug_bounds("omega.omega.route.unavailable").is_none());
        assert!(cx.debug_bounds("omega.omega.thread-tab.active").is_some());
    }

    #[gpui::test]
